// Generated by tools/import_d2r_helmet_art.py - keep base names in sync with D2R armor.txt.
// Helmet GLBs and 256px albedo maps live in assets/d2survivors/models/helmets.

export type D2HelmetVisualId =
  | "cap"
  | "jawbone"
  | "skull"
  | "helm"
  | "full"
  | "great"
  | "bone"
  | "crown"
  | "circlet"
  | "coronet"
  | "diadem"
  | "tiara"
  | "mask"
  | "assault"
  | "avenger"
  | "fanged"
  | "horned"
  | "wolf"
  | "hawk"
  | "antlers"
  | "falcon"
  | "spirit";

export interface D2HelmetVisual {
  id: D2HelmetVisualId;
  model: string;
  texture: string;
  /** Head-bone local scale; all D2R helmet meshes share one authoring scale. */
  scale: number;
  /** Head-bone local lift, used to seat hats on the skull rather than the jaw. */
  lift: number;
  /** Which of the rig's built-in hair layers belongs under this piece. */
  hair: "none" | "half" | "full";
  /** Extra head-local rotation for source meshes authored on another axis. */
  rotation?: [number, number, number];
  metalness: number;
  roughness: number;
}

const HELMET_ROOT = "assets/d2survivors/models/helmets";

function helmet(
  id: D2HelmetVisualId,
  hair: D2HelmetVisual["hair"],
  lift = 0.0009,
  metalness = 0.12,
  roughness = 0.78,
  rotation: [number, number, number] = [0, 0, 0],
): D2HelmetVisual {
  return {
    id,
    model: `${HELMET_ROOT}/${id}.glb`,
    texture: `${HELMET_ROOT}/${id}.png`,
    scale: 0.00305,
    lift,
    hair,
    rotation,
    metalness,
    roughness,
  };
}

