/**
 * Resolve a helmet item to its D2R mesh. The exact base-name table covers every
 * armor.txt tier; the suffix checks keep hand-written drops such as
 * "Stalwart Leather Cap" working even when their base name is not a D2 base.
 */
export function getHelmetVisualForItem(item: { baseName?: string; name: string }): D2HelmetVisual | null {
  const base = (item.baseName ?? "").trim().toLowerCase();
  const exact = D2_HELMET_BASE_VISUALS[base];
  if (exact) return D2_HELMET_VISUALS[exact];

  const name = `${base} ${item.name}`.trim().toLowerCase();
  const fallback: Array<[RegExp, D2HelmetVisualId]> = [
    [/jawbone|carnage helm/, "jawbone"],
    [/fanged|lion helm|fury visor/, "fanged"],
    [/horned|rage mask|destroyer helm/, "horned"],
    [/assault|savage helmet|conqueror crown/, "assault"],
    [/avenger|slayer guard|guardian crown/, "avenger"],
    [/wolf head|blood spirit|dream spirit/, "wolf"],
    [/hawk helm/, "hawk"],
    [/antlers|hunter's guise|earth spirit/, "antlers"],
    [/falcon mask|sun spirit|sky spirit/, "falcon"],
    [/spirit mask|totemic mask/, "spirit"],
    [/circlet/, "circlet"],
    [/coronet/, "coronet"],
    [/tiara/, "tiara"],
    [/diadem/, "diadem"],
    [/bone|grim helm|visage/, "bone"],
    [/great|winged helm|spired/, "great"],
    [/full|basinet|conch/, "full"],
    [/skull|sallet|hydraskull/, "skull"],
    [/cap|war hat|shako/, "cap"],
    [/crown/, "crown"],
    [/mask/, "mask"],
    [/helm/, "helm"],
  ];
  for (const [pattern, id] of fallback) {
    if (pattern.test(name)) return D2_HELMET_VISUALS[id];
  }
  return null;
}
